import { systemClock, type Clock } from "./clock.ts";
import { openDb, type Db } from "./db.ts";
import { CouponRepository } from "./repositories/couponRepository.ts";
import { OrderRepository } from "./repositories/orderRepository.ts";
import { Router, type HttpResponse } from "./router.ts";
import { registerCouponRoutes } from "./routes/coupons.ts";
import { registerOrderRoutes } from "./routes/orders.ts";
import { CouponService } from "./services/couponService.ts";
import { OrderService } from "./services/orderService.ts";

export interface App {
  db: Db;
  request(method: string, path: string, body?: unknown): HttpResponse;
}

export interface AppOptions {
  db?: Db;
  clock?: Clock;
}

/** Wires repositories, services and routes. Tests call app.request(...) in-process. */
export function createApp(options: AppOptions = {}): App {
  const db = options.db ?? openDb();
  const clock = options.clock ?? systemClock;
  const router = new Router();

  const orderRepo = new OrderRepository(db);
  const couponRepo = new CouponRepository(db);
  registerOrderRoutes(router, new OrderService(orderRepo, clock));
  registerCouponRoutes(router, new CouponService(couponRepo));

  return { db, request: (method, path, body) => router.handle(method, path, body) };
}
import { AppError } from "./errors.ts";

export interface HttpResponse {
  status: number;
  body: unknown;
}

export type Handler = (params: Record<string, string>, body: any) => HttpResponse;

interface Route {
  method: string;
  pattern: RegExp;
  keys: string[];
  handler: Handler;
}

/** Minimal path router: "/orders/:id" style patterns, JSON in, JSON out. */
export class Router {
  private readonly routes: Route[] = [];

  add(method: string, path: string, handler: Handler): void {
    const keys: string[] = [];
    const source = path.replace(/:(\w+)/g, (_, k: string) => {
      keys.push(k);
      return "([^/]+)";
    });
    this.routes.push({ method, pattern: new RegExp(`^${source}$`), keys, handler });
  }

  handle(method: string, path: string, body: unknown): HttpResponse {
    for (const r of this.routes) {
      if (r.method !== method) continue;
      const m = r.pattern.exec(path);
      if (!m) continue;
      const params = Object.fromEntries(r.keys.map((k, i) => [k, decodeURIComponent(m[i + 1])]));
      try {
        return r.handler(params, body ?? {});
      } catch (e) {
        if (e instanceof AppError) return { status: e.status, body: { error: { code: e.code, message: e.message } } };
        return { status: 500, body: { error: { code: "INTERNAL_ERROR", message: String(e) } } };
      }
    }
    return { status: 404, body: { error: { code: "ROUTE_NOT_FOUND", message: `${method} ${path}` } } };
  }
}
import { DatabaseSync } from "node:sqlite";

export type Db = DatabaseSync;

const SCHEMA = `
CREATE TABLE IF NOT EXISTS orders (
  id                 INTEGER PRIMARY KEY AUTOINCREMENT,
  customer           TEXT    NOT NULL,
  amount_cents       INTEGER NOT NULL CHECK (amount_cents > 0),
  discount_cents     INTEGER NOT NULL DEFAULT 0,
  final_amount_cents INTEGER NOT NULL,
  coupon_code        TEXT,
  status             TEXT    NOT NULL DEFAULT 'PENDING',   -- PENDING | PAID | CANCELLED
  created_at         TEXT    NOT NULL
);

CREATE TABLE IF NOT EXISTS coupons (
  code               TEXT    PRIMARY KEY,
  type               TEXT    NOT NULL,                     -- FIXED | PERCENT
  value              INTEGER NOT NULL,                     -- FIXED: cents; PERCENT: 0..100
  min_amount_cents   INTEGER NOT NULL DEFAULT 0,
  max_discount_cents INTEGER,                              -- NULL = no cap
  valid_from         TEXT    NOT NULL,                     -- ISO-8601 UTC
  valid_until        TEXT    NOT NULL,                     -- ISO-8601 UTC
  status             TEXT    NOT NULL DEFAULT 'ACTIVE',    -- ACTIVE | DISABLED
  usage_limit        INTEGER,                              -- NULL = unlimited
  used_count         INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS coupon_redemptions (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id       INTEGER NOT NULL REFERENCES orders(id),
  coupon_code    TEXT    NOT NULL REFERENCES coupons(code),
  discount_cents INTEGER NOT NULL,
  created_at     TEXT    NOT NULL
);
`;

export function openDb(path = ":memory:"): Db {
  const db = new DatabaseSync(path);
  db.exec("PRAGMA foreign_keys = ON");
  db.exec(SCHEMA);
  return db;
}
/** Every error response has the shape { "error": { "code": ..., "message": ... } }. */
export class AppError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

export const notFound = (code: string, message: string) => new AppError(404, code, message);
export const badRequest = (code: string, message: string) => new AppError(400, code, message);
export const conflict = (code: string, message: string) => new AppError(409, code, message);
/** Current time source. Inject a fixed clock in tests instead of reading the system time. */
export type Clock = () => Date;

export const systemClock: Clock = () => new Date();

