const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync(':memory:');
db.exec('CREATE TABLE t(id INTEGER PRIMARY KEY, v TEXT)');
console.log('has transaction fn:', typeof db.transaction);
db.exec('BEGIN IMMEDIATE');
db.prepare('INSERT INTO t(v) VALUES (?)').run('a');
db.exec('ROLLBACK');
console.log('rows after rollback:', db.prepare('SELECT COUNT(*) c FROM t').get().c);
db.exec('BEGIN IMMEDIATE');
db.prepare('INSERT INTO t(v) VALUES (?)').run('b');
db.exec('COMMIT');
console.log('rows after commit:', db.prepare('SELECT COUNT(*) c FROM t').get().c);
\" 2>&1"

